Here is the commit message:
bnxt_en: set backing store type from query type

bnxt_hwrm_func_backing_store_qcaps_v2() stores resp->type from the
firmware response in ctxm->type and later uses that value to index
fixed backing-store metadata arrays such as ctx_arr[] and
bnxt_bstore_to_trace[].

ctxm->type is fixed by the current backing-store query type and matches
the array index of ctx->ctx_arr. Set ctxm->type from the current loop
variable instead of depending on resp->type.

Also update the loop to advance type from next_valid_type in the for
statement, which keeps the control flow simpler for non-valid and
unchanged entries.

Fixes: 6a4d0774f02d ("bnxt_en: Add support for new backing store query firmware API")
Signed-off-by: Pengpeng Hou <pengpeng@iscas.ac.cn>
Reviewed-by: Michael Chan <michael.chan@broadcom.com>
Tested-by: Michael Chan <michael.chan@broadcom.com>
Link: https://patch.msgid.link/20260328234357.43669-1-pengpeng@iscas.ac.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is due to two interrelated issues in `bnxt_hwrm_func_backing_store_qcaps_v2()`. First, `ctxm->type` was set from `resp->type` (the firmware's reported type field) instead of the current loop index `type`. Since `ctxm->type` is later used to index fixed backing-store metadata arrays (like `ctx_arr[]` and `bnxt_bstore_to_trace[]`), using the firmware-provided value could cause incorrect indexing when the firmware returns a type different from the current array index. Second, the loop variable `type` was overwritten by `resp->next_valid_type` directly in the loop body, making loop control fragile and causing skipped or incorrect iterations when encountering invalid or unchanged entries.

Here is the patch:

 static int bnxt_hwrm_func_backing_store_qcaps_v2(struct bnxt *bp)
 {
 	struct hwrm_func_backing_store_qcaps_v2_output *resp;
 	struct hwrm_func_backing_store_qcaps_v2_input *req;
 	struct bnxt_ctx_mem_info *ctx = bp->ctx;
-	u16 type;
+	u16 type, next_type = 0;
 	int rc;

 	rc = hwrm_req_init(bp, req, HWRM_FUNC_BACKING_STORE_QCAPS_V2);
 	if (rc)
 		return rc;

 	if (!ctx) {
 		ctx = kzalloc_obj(*ctx);
 		if (!ctx)
 			return -ENOMEM;
 		bp->ctx = ctx;
 	}

 	resp = hwrm_req_hold(bp, req);

-	for (type = 0; type < BNXT_CTX_V2_MAX; ) {
+	for (type = 0; type < BNXT_CTX_V2_MAX; type = next_type) {
 		struct bnxt_ctx_mem_type *ctxm = &ctx->ctx_arr[type];
 		u8 init_val, init_off, i;
 		u32 max_entries;
 		u16 entry_size;
 		__le32 *p;
 		u32 flags;

 		req->type = cpu_to_le16(type);
 		rc = hwrm_req_send(bp, req);
 		if (rc)
 			goto ctx_done;
 		flags = le32_to_cpu(resp->flags);
-		type = le16_to_cpu(resp->next_valid_type);
+		next_type = le16_to_cpu(resp->next_valid_type);
 		if (!(flags & BNXT_CTX_MEM_TYPE_VALID)) {
 			bnxt_free_one_ctx_mem(bp, ctxm, true);
 			continue;
 		}
 		entry_size = le16_to_cpu(resp->entry_size);
 		max_entries = le32_to_cpu(resp->max_num_entries);
 		if (ctxm->mem_valid) {
 			if (!(flags & BNXT_CTX_MEM_PERSIST) ||
 			    ctxm->entry_size != entry_size ||
 			    ctxm->max_entries != max_entries)
 				bnxt_free_one_ctx_mem(bp, ctxm, true);
 			else
 				continue;
 		}
-		ctxm->type = le16_to_cpu(resp->type);
+		ctxm->type = type;
 		ctxm->entry_size = entry_size;
 		ctxm->flags = flags;
 		ctxm->instance_bmap = le32_to_cpu(resp->instance_bit_map);
 		ctxm->entry_multiple = resp->entry_multiple;
 		ctxm->max_entries = max_entries;
 		ctxm->min_entries = le32_to_cpu(resp->min_num_entries);
 		init_val = resp->ctx_init_value;
 		init_off = resp->ctx_init_offset;
 		bnxt_init_ctx_initializer(ctxm, init_val, init_off,
 					  BNXT_CTX_INIT_VALID(flags));
 		ctxm->split_entry_cnt = min_t(u8, resp->subtype_valid_cnt,
 					      BNXT_MAX_SPLIT_ENTRY);
 		for (i = 0, p = &resp->split_entry_0; i < ctxm->split_entry_cnt;
 		     i++, p++)
 			ctxm->split[i] = le32_to_cpu(*p);
 	}
 	rc = bnxt_alloc_all_ctx_pg_info(bp, BNXT_CTX_V2_MAX);

 ctx_done:
 	hwrm_req_drop(bp, req);
 	return rc;
 }



